class Solution {
public:
    long long subsequenceSumOr(std::vector<int>& nums) {
        long long ans = 0;
        long long prefix = 0;
        for (int x : nums) {
            prefix += x;
            ans |= (long long)x | prefix;
        }
        return ans;
    }
};

class Solution {
    public long subsequenceSumOr(int[] nums) {
        long ans = 0;
        long prefix = 0;
        for (int x : nums) {
            prefix += x;
            ans |= (long)x | prefix;
        }
        return ans;
    }
}

var subsequenceSumOr = function(nums) {
    let ans = 0n;
    let prefix = 0n;
    for (const x of nums) {
        const bx = BigInt(x);
        prefix += bx;
        ans |= bx | prefix;
    }
    return Number(ans);
};
